package com.javainterview.rag.interview.persistence;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.javainterview.rag.interview.evaluation.*; import java.util.*;
public final class MySqlAnswerExperimentStore implements AnswerExperimentStore {
 private static final TypeReference<List<AnswerExperimentCaseResult>> CASES=new TypeReference<>(){}; private final AnswerExperimentRunMapper mapper; private final ObjectMapper json;
 public MySqlAnswerExperimentStore(AnswerExperimentRunMapper mapper,ObjectMapper json){this.mapper=mapper;this.json=json;}
 public AnswerExperimentRun createOrFind(AnswerExperimentRun run){mapper.insert(entity(run)); AnswerExperimentRunEntity e=mapper.findByContract(run.contractHash()); if(e==null)throw new IllegalStateException("回答实验创建失败");return run(e);}
 public Optional<AnswerExperimentRun> find(String id){AnswerExperimentRunEntity e=mapper.find(id);return e==null?Optional.empty():Optional.of(run(e));}
 public List<AnswerExperimentRun> findRecent(int limit){return mapper.recent(limit).stream().map(this::run).toList();}
 public List<AnswerExperimentRun> findRecoverable(){return mapper.recoverable().stream().map(this::run).toList();}
 public void saveProgress(String id,AnswerExperimentStatus status,List<AnswerExperimentCaseResult> results,AnswerExperimentReport report,String error,boolean completed){try{mapper.progress(id,status.name(),json.writeValueAsString(results),report==null?null:json.writeValueAsString(report),error,completed);}catch(Exception e){throw new IllegalStateException("回答实验结果保存失败",e);}}
 public void saveDecision(String c,String b,AnswerExperimentDecision d,String n){if(mapper.decision(c,b,d.name(),n)==0)throw new IllegalStateException("回答实验不存在");}
 private AnswerExperimentRunEntity entity(AnswerExperimentRun r){try{AnswerExperimentRunEntity e=new AnswerExperimentRunEntity();e.setRunId(r.runId());e.setName(r.name());e.setDatasetVersion(r.datasetVersion());e.setPromptVersion(r.promptVersion());e.setRubricVersion(r.rubricVersion());e.setModelName(r.modelName());e.setContractHash(r.contractHash());e.setStatus(r.status().name());e.setTotalCaseCount(r.totalCaseCount());e.setCaseResultsJson(json.writeValueAsString(r.caseResults()));e.setCreatedAt(r.createdAt());e.setUpdatedAt(r.updatedAt());return e;}catch(Exception x){throw new IllegalStateException("回答实验序列化失败",x);}}
 private AnswerExperimentRun run(AnswerExperimentRunEntity e){try{return new AnswerExperimentRun(e.getRunId(),e.getName(),e.getDatasetVersion(),e.getPromptVersion(),e.getRubricVersion(),e.getModelName(),e.getContractHash(),AnswerExperimentStatus.valueOf(e.getStatus()),e.getTotalCaseCount(),json.readValue(e.getCaseResultsJson(),CASES),e.getReportJson()==null?null:json.readValue(e.getReportJson(),AnswerExperimentReport.class),e.getErrorType(),e.getBaselineRunId(),e.getDecision()==null?null:AnswerExperimentDecision.valueOf(e.getDecision()),e.getDecisionNote(),e.getCreatedAt(),e.getUpdatedAt(),e.getCompletedAt(),e.getDecidedAt());}catch(Exception x){throw new IllegalStateException("回答实验反序列化失败",x);}}
}
